questionvariables.text:
/* Shared Question Bank Place Value, Rounding and Standard Form PVRS-01
Foundation task: identify the value represented by a digit according to its position.
This question is curriculum-independent. */
/* Generate a six-digit whole number.
The thousands digit is deliberately kept non-zero so its positional value is always meaningful and distinguishable from zero. */
hundred_thousands_digit: rand_with_prohib(1,9,[]);
ten_thousands_digit: rand_with_prohib(0,9,[]);
thousands_digit: rand_with_prohib(1,9,[]);
hundreds_digit: rand_with_prohib(0,9,[]);
tens_digit: rand_with_prohib(0,9,[]);
ones_digit: rand_with_prohib(0,9,[]);
/* Construct the displayed number. */
number: hundred_thousands_digit*100000 +ten_thousands_digit*10000 +thousands_digit*1000 +hundreds_digit*100 +tens_digit*10 +ones_digit;
/* Teacher answer. */
answer: thousands_digit*1000;
/* Target misconception:
The learner identifies the correct digit but gives the digit itself rather than its positional value.
Example: digit = 7 incorrect response = 7 correct response = 7000 */
wrong_digit_only: thousands_digit;
